#!/usr/bin/env bash
# Covers upload_r8_mapping.sh. The step it replaced ran only on a tag push and
# is deliberately unfailable - every unplanned fault becomes `exit 0` plus a
# summary line, because a release must not be discarded over Sentry - so this
# suite is the only thing left that can turn a regression in it red.
#
# Offline: `SENTRY_CLI` points at a stub that records its argv, so the happy
# path asserts the exact command rather than that something was attempted.
# That is the one case pinning both parsers at once - the UUID read out of an
# APK and the two slugs read out of a pubspec - and the only one that catches a
# slug passed through with its quotes still attached.
#
# An APK is a zip, so the fixtures are built with python's zipfile and need no
# Android toolchain. Every case asserts the message, not merely the exit
# status: the script exits 0 on almost everything, so the status alone would
# satisfy nearly the whole suite.
set -Eeuo pipefail

HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
SCRIPT="$HERE/upload_r8_mapping.sh"

# Said once and plainly, because the subject reads an APK through a helper that
# swallows `unzip`'s own errors on purpose - absence and unreadability are one
# outcome there - so without this a box with no `unzip` fails six cases with a
# message about a missing UUID and nothing about the missing tool.
for tool in unzip python3 sha256sum curl; do
  if ! command -v "$tool" > /dev/null 2>&1; then
    echo "::error::$tool is needed to run this suite and is not installed." >&2
    exit 1
  fi
done
TMP="$(mktemp -d)"
trap 'rm -rf "$TMP"' EXIT
failures=0

pass() { printf '  ok    %s\n' "$1"; }
fail() {
  printf '  FAIL  %s\n' "$1"
  [[ -n "${2:-}" ]] && printf '%s\n' "$2" | sed 's/^/          /'
  failures=$((failures + 1))
}

# A stub sentry-cli: records argv, exits with $STUB_EXIT.
#
# Appends, because a release uploads two mappings - one for the APKs and one
# for the App Bundle - and overwriting would leave the suite asserting
# whichever happened to go last.
cat > "$TMP/sentry-cli" <<'STUB'
#!/usr/bin/env bash
printf '%s\n' "$*" >> "$STUB_ARGV"
exit "${STUB_EXIT:-0}"
STUB
chmod +x "$TMP/sentry-cli"

# What a release leaves behind, since AGP forces two R8 runs: `mapping.txt` is
# the App Bundle's, because R8 writes that name and the bundle goes last, and
# `mapping-apk.txt` is the one `android.sh` moved aside first. The two UUIDs
# differ for the same reason, and that is the point - each mapping is filed
# under the UUID of the artifact it describes.
UUID='1d0c7dd0-d7e4-3ad8-9c9f-9c6f0c75a5b1'
AAB_UUID='c334941f-732a-395c-b01a-f421150beef6'

# workspace <name> [apk-uuid-line] [aab-uuid-line] -> a dir with both mappings,
# a universal APK, an App Bundle and a pubspec. Pass an empty uuid line for an
# artifact whose properties carry no UUID.
workspace() {
  local name="$1"
  local apk_line="${2-io.sentry.ProguardUuids=$UUID}"
  local aab_line="${3-io.sentry.ProguardUuids=$AAB_UUID}"
  local d="$TMP/$name"
  rm -rf "$d"; mkdir -p "$d/dist" "$d/mapdir" "$d/tmp"
  printf '# compiler: R8\n# pg_map_hash: SHA-256 aab\na.b.C -> x.y:\n' > "$d/mapdir/mapping.txt"
  printf '# compiler: R8\n# pg_map_hash: SHA-256 apk\na.b.C -> x.y:\n' > "$d/mapdir/mapping-apk.txt"
  printf 'name: qunleashed\n\nsentry:\n  upload_debug_symbols: true\n  org: dark-flippers\n  project: qunleashed\n\nflutter:\n  generate: true\n' > "$d/pubspec.yaml"
  python3 - "$d/dist" "$apk_line" "$aab_line" <<'PY'
import os, sys, zipfile
dist, apk_line, aab_line = sys.argv[1], sys.argv[2], sys.argv[3]

def props(line):
    body = "# Generated by sentry-android-gradle-plugin\n"
    if line:
        body += line + "\n"
    return body + "io.sentry.build-tool=gradle\n"

with zipfile.ZipFile(os.path.join(dist, "qunleashed_0.17.0_android_universal.apk"), "w") as z:
    z.writestr("AndroidManifest.xml", "manifest")
    z.writestr("assets/sentry-debug-meta.properties", props(apk_line))

with zipfile.ZipFile(os.path.join(dist, "qunleashed_0.17.0_android.aab"), "w") as z:
    z.writestr("base/manifest/AndroidManifest.xml", "manifest")
    z.writestr("base/assets/sentry-debug-meta.properties", props(aab_line))
PY
  : > "$d/summary.md"
  echo "$d"
}

# run <dir> -> stdout+stderr; env additions come from the caller
run() {
  local d="$1"; shift
  ( cd "$d" \
      && GITHUB_STEP_SUMMARY="$d/summary.md" \
         SENTRY_RELEASE="qunleashed@0.17.0-dev+1" \
         RUNNER_TEMP="$d/tmp" \
         STUB_ARGV="$d/argv" \
         SENTRY_CLI="$TMP/sentry-cli" \
         env "$@" bash "$SCRIPT" "$d/dist" "$d/mapdir" "$d/pubspec.yaml" 2>&1 )
}

# says <label> <dir> <expected-in-output> <expected-in-summary>
says() {
  local label="$1" d="$2" want_out="$3" want_sum="$4" out rc
  out="$(run "$d" SENTRY_AUTH_TOKEN=sntrys_stub)" && rc=0 || rc=$?
  if [[ "$rc" -ne 0 ]]; then fail "$label (exit $rc)" "$out"; return; fi
  if [[ "$out" != *"$want_out"* ]]; then
    fail "$label (annotation)" "$out"; return
  fi
  if ! grep -qF -- "$want_sum" "$d/summary.md"; then
    fail "$label (job summary)" "$(cat "$d/summary.md")"; return
  fi
  pass "$label"
}

echo "upload_r8_mapping.sh"

# --- the happy path, which pins both parsers at once ------------------------

d="$(workspace happy)"
out="$(run "$d" SENTRY_AUTH_TOKEN=sntrys_stub)" || fail "a good upload succeeds" "$out"
want_apk="proguard upload --require-one --uuid $UUID --org dark-flippers --project qunleashed $d/mapdir/mapping-apk.txt"
want_aab="proguard upload --require-one --uuid $AAB_UUID --org dark-flippers --project qunleashed $d/mapdir/mapping.txt"
got="$(cat "$d/argv")"
if [[ "$got" == *"$want_apk"* ]]; then
  pass "the APKs' mapping is sent under the APK's own UUID"
else
  fail "the APKs' mapping is sent under the APK's own UUID" \
    "wanted: $want_apk"$'\n'"got:    $got"
fi
# The half that would otherwise be silent: two R8 runs mean the bundle has its
# own UUID, and a mapping filed under the APKs' would leave every Play user's
# Java frames reading as confident wrong names.
if [[ "$got" == *"$want_aab"* ]]; then
  pass "the bundle's mapping is sent under the bundle's own UUID"
else
  fail "the bundle's mapping is sent under the bundle's own UUID" \
    "wanted: $want_aab"$'\n'"got:    $got"
fi
if (( $(grep -c . <<<"$got") == 2 )); then
  pass "exactly two mappings are uploaded"
else
  fail "exactly two mappings are uploaded" "$got"
fi
if grep -q "R8 mappings uploaded" "$d/summary.md"; then
  pass "...and the job summary says so"
else
  fail "...and the job summary says so" "$(cat "$d/summary.md")"
fi

# A quoted slug is a plausible YAML edit that sentry_dart_plugin would survive,
# so it must not reach --org with its quotes on.
d="$(workspace quoted-slug)"
printf 'name: qunleashed\n\nsentry:\n  org: "dark-flippers"\n  project: '"'"'qunleashed'"'"'  # the project\n\nflutter:\n' > "$d/pubspec.yaml"
out="$(run "$d" SENTRY_AUTH_TOKEN=sntrys_stub)" || fail "a quoted slug still uploads" "$out"
if [[ "$(cat "$d/argv")" == *"--org dark-flippers --project qunleashed "* ]]; then
  pass "quotes and a trailing comment are not part of a slug"
else
  fail "quotes and a trailing comment are not part of a slug" "got: $(cat "$d/argv")"
fi

# --- the quiet paths --------------------------------------------------------

# A job that built no APK never ran R8. The only wholly silent outcome.
d="$(workspace no-mapping)"; rm -f "$d"/mapdir/*; rm -f "$d"/dist/*
out="$(run "$d" SENTRY_AUTH_TOKEN=sntrys_stub)" || fail "a job that built nothing leaves quietly" "$out"
if [[ -z "$out" && ! -s "$d/summary.md" && ! -f "$d/argv" ]]; then
  pass "a job that built nothing leaves quietly"
else
  fail "a job that built nothing leaves quietly" "$out"$'\n'"$(cat "$d/summary.md")"
fi

# No token is not an error, and is not reported twice: the debug-files step in
# the same action has already said it.
d="$(workspace no-token)"
out="$(run "$d" SENTRY_AUTH_TOKEN=)" || fail "no token is not an error" "$out"
if [[ -z "$out" && ! -s "$d/summary.md" && ! -f "$d/argv" ]]; then
  pass "no token is not an error, and is not reported twice"
else
  fail "no token is not an error, and is not reported twice" "$out"$'\n'"$(cat "$d/summary.md")"
fi

# --- the loud paths --------------------------------------------------------

# An Android job with no mapping is #343 again, and must not look like a
# correct macOS run.
d="$(workspace android-no-mapping)"; rm -f "$d/mapdir/mapping-apk.txt"
says "Android APKs with no mapping are reported" "$d" \
  "No R8 mapping for the APKs" "no mapping at"

# The same fault on the other half, which is the one that reaches store users.
d="$(workspace bundle-no-mapping)"; rm -f "$d/mapdir/mapping.txt"
says "an App Bundle with no mapping is reported" "$d" \
  "No R8 mapping for the App Bundle" "no mapping at"

d="$(workspace no-apk)"; rm -f "$d"/dist/*.apk
says "a mapping with no universal APK is reported" "$d" \
  "no such artifact is in" "no artifact to read its UUID from"

d="$(workspace no-bundle)"; rm -f "$d"/dist/*.aab
says "a mapping with no App Bundle is reported" "$d" \
  "no such artifact is in" "no artifact to read its UUID from"

d="$(workspace no-uuid "")"
says "an APK with no UUID is reported" "$d" \
  "no usable io.sentry.ProguardUuids" "could not be addressed"

d="$(workspace bundle-no-uuid "io.sentry.ProguardUuids=$UUID" "")"
says "a bundle with no UUID is reported" "$d" \
  "no usable io.sentry.ProguardUuids" "could not be addressed"

# The key is plural and the SDK reads it as a list; both readers assume one.
# A pair has to be refused here rather than truncated to the first.
d="$(workspace two-uuids "io.sentry.ProguardUuids=$UUID,2d0c7dd0-d7e4-3ad8-9c9f-9c6f0c75a5b2")"
says "an APK carrying two UUIDs is reported" "$d" \
  "no usable io.sentry.ProguardUuids" "could not be addressed"

d="$(workspace malformed-uuid "io.sentry.ProguardUuids=not-a-uuid")"
says "an APK carrying a malformed UUID is reported" "$d" \
  "no usable io.sentry.ProguardUuids" "could not be addressed"

# sentry-cli failing must cost a warning, not the release.
d="$(workspace upload-fails)"
out="$(run "$d" SENTRY_AUTH_TOKEN=sntrys_stub STUB_EXIT=1)" && rc=0 || rc=$?
if [[ "$rc" -ne 0 ]]; then
  fail "a failed upload does not fail the step" "exit $rc"
elif [[ "$out" != *"Uploading the R8 mapping for the APKs failed"* ]]; then
  fail "a failed upload is reported, naming which half" "$out"
elif [[ "$out" != *"Uploading the R8 mapping for the App Bundle failed"* ]]; then
  fail "both halves are reported when both fail" "$out"
elif ! grep -qF -- "proguard upload --uuid $UUID --org dark-flippers" "$d/summary.md"; then
  fail "a failed upload prints a re-upload command that would work" "$(cat "$d/summary.md")"
elif ! grep -qF -- "proguard upload --uuid $AAB_UUID --org dark-flippers" "$d/summary.md"; then
  fail "the re-upload command for the bundle is printed too" "$(cat "$d/summary.md")"
else
  pass "a failed upload is reported per half, does not fail the step, and says how to redo it"
fi

# One half failing must not take the other with it, and the summary has to say
# which one went: the bundle is what Play installs, so "uploaded" alone would
# hide the half that matters. The stub fails only for the APK mapping.
cat > "$TMP/sentry-cli-apk-fails" <<'STUB'
#!/usr/bin/env bash
printf '%s\n' "$*" >> "$STUB_ARGV"
[[ "$*" == *mapping-apk.txt ]] && exit 1
exit 0
STUB
chmod +x "$TMP/sentry-cli-apk-fails"
d="$(workspace one-half-fails)"
out="$(run "$d" SENTRY_AUTH_TOKEN=sntrys_stub SENTRY_CLI="$TMP/sentry-cli-apk-fails")" && rc=0 || rc=$?
if [[ "$rc" -ne 0 ]]; then
  fail "one half failing does not fail the step" "exit $rc"
elif [[ "$out" != *"for the APKs failed"* || "$out" == *"for the App Bundle failed"* ]]; then
  fail "only the half that failed is reported as failed" "$out"
elif ! grep -qF -- "\`$AAB_UUID\` for the App Bundle" "$d/summary.md"; then
  fail "the half that succeeded is still reported as uploaded" "$(cat "$d/summary.md")"
else
  pass "one half failing leaves the other uploaded, and the summary names both"
fi

# --- the one hard failure --------------------------------------------------

# An unreadable pubspec breaks every upload, not only this one, so it is the
# single outcome allowed to exit non-zero.
d="$(workspace no-slugs)"
printf 'name: qunleashed\n' > "$d/pubspec.yaml"
out="$(run "$d" SENTRY_AUTH_TOKEN=sntrys_stub)" && rc=0 || rc=$?
if [[ "$rc" -eq 0 ]]; then
  fail "a pubspec with no sentry block is refused (was accepted)" "$out"
elif [[ "$out" != *"Could not read both slugs"* ]]; then
  fail "a pubspec with no sentry block is refused (wrong reason)" "$out"
elif ! grep -q "did not yield both slugs" "$d/summary.md"; then
  fail "a pubspec with no sentry block says so in the job summary" "$(cat "$d/summary.md")"
else
  pass "a pubspec with no sentry block is refused, loudly"
fi

# --- the download and its checksum -----------------------------------------

# The one branch the `SENTRY_CLI` seam skips past. Only the URL is overridable
# - the version and the checksum are `readonly`, so a pin cannot be lowered
# from outside - which means pointing it at anything else is a guaranteed
# mismatch, and that is exactly the branch worth covering.
d="$(workspace bad-checksum)"
printf 'not sentry-cli\n' > "$d/decoy"
# `cygpath` only when running the suite by hand on Windows: curl there is a
# native binary and cannot open an MSYS path. CI is ubuntu-only.
decoy="file://$d/decoy"
if command -v cygpath > /dev/null 2>&1; then
  decoy="file:///$(cygpath -m "$d/decoy")"
fi
out="$(run "$d" SENTRY_AUTH_TOKEN=sntrys_stub SENTRY_CLI= SENTRY_CLI_URL="$decoy")" && rc=0 || rc=$?
if [[ "$rc" -ne 0 ]]; then
  fail "a download that fails its checksum does not fail the step" "exit $rc"
elif [[ "$out" != *"did not match its pinned SHA256"* ]]; then
  fail "a download that fails its checksum is reported" "$out"
elif [[ "$out" != *"::error::"* ]]; then
  fail "a bad checksum is an error, not a warning" "$out"
elif [[ -f "$d/argv" ]]; then
  fail "a download that fails its checksum is not executed" "it ran: $(cat "$d/argv")"
else
  pass "a download failing its checksum is an error, is not executed, and does not fail the step"
fi

# --- the pin ----------------------------------------------------------------

# Catches a half-done version bump, which otherwise fails only on a tagged
# release. No network: the declarations are read out of the script.
version="$(sed -nE 's/^readonly SENTRY_CLI_VERSION="([^"]+)"$/\1/p' "$SCRIPT")"
sha="$(sed -nE 's/^readonly SENTRY_CLI_SHA256="([^"]+)"$/\1/p' "$SCRIPT")"
url="$(sed -nE 's/^SENTRY_CLI_URL="(.*)"$/\1/p' "$SCRIPT")"
# The URL is asserted to interpolate the pin rather than to spell a version of
# its own, which is the half-done bump that would otherwise fetch one version
# and check the other's checksum. The single quotes are the point: this matches
# the unexpanded text of the declaration.
# shellcheck disable=SC2016
if [[ -n "$version" && "$sha" =~ ^[0-9a-f]{64}$ && "$url" == *'${SENTRY_CLI_VERSION}'* ]]; then
  pass "the pinned sentry-cli has a 64-hex checksum and a URL built from the pin"
else
  fail "the pinned sentry-cli has a 64-hex checksum and a URL built from the pin" \
    "version=$version sha=$sha url=$url"
fi

if (( failures )); then
  echo "$failures failure(s)" >&2
  exit 1
fi
echo "all passed"
